        strcat('$d=$',sprintf("%.0f", d_vector(d_idx_plot(2))*1e6),'$\mu$m')... %[output:60e93672]
        strcat('$d=$',sprintf("%.0f", d_vector(d_idx_plot(3))*1e6),'$\mu$m')... %[output:60e93672]
        },'Interpreter','latex'); %[output:60e93672]
xlabel('Time [min]','Interpreter','latex'); %[output:60e93672]
ylabel('AMP: $m_\mathrm{in}$ [mM]','Interpreter','latex'); %[output:60e93672]
