% Differentiator 1: the two delay pools
figure; %[output:1aba1d87]
plot(t/60,m_Sd(:,1),'LineWidth',3); grid on; hold on %[output:1aba1d87]
plot(t/60,m_Sd(:,5),'--','LineWidth',3); %[output:1aba1d87]
% plot(t/60,m_Sd_1(:,10),'o-','MarkerIndices',ceil((1:4*60*1/dt0:length(t))),'LineWidth',3);
xlabel('Time [min]','Interpreter','latex'); %[output:1aba1d87]
xlim([0 40]) %[output:1aba1d87]
% axis([0 t_end m_in(40*round(60/dt0)) 1.001*max(m_in(:,1))])
ylabel('NADH: $m_{d1}$ [mM]','Interpreter','latex'); %[output:1aba1d87]
set(gca,'FontSize',fontsize+20); %[output:1aba1d87]

yyaxis right %[output:1aba1d87]
delta_t_s=round((tau_S_1-tau_F_1)/dt);
m_d1_analy=(m_in(1:end-delta_t_s,1)-m_in(delta_t_s+1:end,1));
plot(t(1:end-delta_t_s)/60,m_d1_analy,'--','LineWidth',3); grid on; hold on %[output:1aba1d87]
m_d1_analy_5=(m_in(1:end-delta_t_s,5)-m_in(delta_t_s+1:end,5));
plot(t(1:end-delta_t_s)/60,m_d1_analy_5,'-','LineWidth',3); %[output:1aba1d87]

